CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY,name TEXT NOT NULL,email TEXT UNIQUE NOT NULL,salt TEXT NOT NULL,hash TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'student');
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),expiry INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS menu(id INTEGER PRIMARY KEY,name TEXT NOT NULL,category TEXT NOT NULL,price INTEGER NOT NULL,stock INTEGER NOT NULL CHECK(stock>=0),minutes INTEGER NOT NULL,emoji TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS orders(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL REFERENCES users(id),created TEXT NOT NULL,status TEXT NOT NULL,payment TEXT NOT NULL,paid INTEGER NOT NULL,total INTEGER NOT NULL,items TEXT NOT NULL,request_id TEXT NOT NULL,UNIQUE(user_id,request_id));
CREATE TABLE IF NOT EXISTS notices(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL,body TEXT NOT NULL,created TEXT NOT NULL);
CREATE TRIGGER IF NOT EXISTS stock_check BEFORE INSERT ON orders BEGIN SELECT CASE WHEN EXISTS(SELECT 1 FROM json_each(NEW.items) j LEFT JOIN menu m ON m.id=json_extract(j.value,'$.id') WHERE m.id IS NULL OR m.stock<json_extract(j.value,'$.qty') OR m.price!=json_extract(j.value,'$.price')) THEN RAISE(ABORT,'Stock or price changed') END; END;
CREATE TRIGGER IF NOT EXISTS stock_decrement AFTER INSERT ON orders BEGIN UPDATE menu SET stock=stock-(SELECT json_extract(j.value,'$.qty') FROM json_each(NEW.items) j WHERE json_extract(j.value,'$.id')=menu.id) WHERE id IN (SELECT json_extract(value,'$.id') FROM json_each(NEW.items)); INSERT INTO notices(user_id,body,created) VALUES(NEW.user_id,'Order T-'||printf('%04d',NEW.id)||' received.',NEW.created); END;
CREATE TRIGGER IF NOT EXISTS status_notice AFTER UPDATE OF status ON orders WHEN NEW.status!=OLD.status BEGIN INSERT INTO notices(user_id,body,created) VALUES(NEW.user_id,'Order T-'||printf('%04d',NEW.id)||': '||NEW.status,strftime('%Y-%m-%dT%H:%M:%S','now','+5 hours','+30 minutes')); END;
